"use client";
import{useEffect,useState,useSyncExternalStore}from'react';import{createRaceSession}from'@pelotonia/race-viewer';import RaceSessionClient from './RaceSessionClient';
export default function Page(){const[session]=useState(()=>createRaceSession({load:async(raceId,{signal})=>{const response=await fetch('/demo-feed-v1.json',{signal});if(!response.ok)throw Error('Missing fixture');const feed=await response.json();return{feed:{...feed,raceId},clock:{position:239.5,serverEpochMs:Date.now(),duration:raceId==='invalid'?feed.duration+1:feed.duration,paused:true,rate:1},revision:0}}}));useEffect(()=>{session.open('session-demo');return()=>session.close()},[session]);const state=useSyncExternalStore(session.subscribe,session.getSnapshot,session.getSnapshot);return <main><p role="status">{state.status} · {state.active?.raceId || 'No active race'} · {state.active?.clock.position}</p><button onClick={()=>session.open('session-B')}>Switch to race B</button><button onClick={()=>session.open('invalid')}>Load invalid replacement</button><h1>Isolated session consumer</h1><RaceSessionClient session={session}/><RaceSessionClient session={session}/></main>}
